    function runPackageWorker(action,input){
      if(typeof root.Worker!=='function')return Promise.reject(new Error('LOCAL_WORKER_UNAVAILABLE_USE_LOCAL_HTTP'));
      return new Promise((resolve,reject)=>{
        let activeWorker;
        try{activeWorker=new root.Worker('./platform-study-worker-v19.js');}catch(error){reject(new Error(error.name==='SecurityError'?'LOCAL_WORKER_UNAVAILABLE_USE_LOCAL_HTTP':'LOCAL_WORKER_FAILED'));return;}
        const requestId=`PACKAGE-${++workerSequence}`;
        let settled=false;
        worker=activeWorker;workerCancellable=true;workerStage='VERIFYING';
        const finish=(error,value)=>{if(settled)return;settled=true;root.clearTimeout(timer);activeWorker.terminate();if(worker===activeWorker){worker=null;cancelWorker=null;workerStage='';workerCancellable=false;}error?reject(error):resolve(value);};
        const timer=root.setTimeout(()=>finish(new Error('PACKAGE_PREVIEW_TIMEOUT')),120000);
        cancelWorker=()=>finish(new Error('CANCELLED_NO_ADOPTION'));
        activeWorker.onerror=()=>finish(new Error('LOCAL_WORKER_FAILED'));
        activeWorker.onmessage=event=>{const value=event.data;if(settled||value.requestId!==requestId||worker!==activeWorker)return;if(value.type==='STAGE'){workerStage=value.stage;workerCancellable=value.cancellable;render();}else if(value.type==='ERROR')finish(new Error(value.code));else if(value.type==='RESULT')finish(null,value.result);};
        try{activeWorker.postMessage({action,input,requestId});render();}catch(error){finish(error);}
      });
    }
